const body = $input.first().json.body || $input.first().json || {};
const nomFichier = (body.nom_fichier || 'tableur_jarvis.xlsx').trim();
const colonnes = Array.isArray(body.colonnes) ? body.colonnes : [];
const lignes = Array.isArray(body.lignes) ? body.lignes : [];

const items = [];
if (lignes.length > 0) {
  for (const row of lignes) {
    const rowObj = {};
    colonnes.forEach((col, idx) => {
      rowObj[col] = (Array.isArray(row) && row[idx] !== undefined) ? row[idx] : '';
    });
    items.push({ json: rowObj });
  }
} else {
  const emptyObj = {};
  colonnes.forEach(c => emptyObj[c] = '');
  items.push({ json: emptyObj });
}

return items;

const body = $input.first().json.body || $input.first().json || {};
const titre = (body.titre || 'Présentation Jarvis').trim();
const subtitle = (body.subtitle || '').trim();
const theme = (body.theme || 'stark').trim().toLowerCase();
const slides = Array.isArray(body.slides) ? body.slides : [];
const batchRequests = Array.isArray(body.batch_requests) ? body.batch_requests : [];
const cleanSlug = (body.clean_slug || titre.replace(/[^a-zA-Z0-9_-]/g, '_').toLowerCase()) || 'presentation';

return [{
  json: {
    titre: titre,
    subtitle: subtitle,
    theme: theme,
    slides: slides,
    slides_count: slides.length,
    batch_requests: batchRequests,
    clean_slug: cleanSlug,
    filename: cleanSlug + '.pptx',
    downloads_path: '/home/opc/jarvis-core/downloads/' + cleanSlug + '.pptx',
    download_url: '/downloads/' + cleanSlug + '.pptx'
  }
}];

const prep = $node['Préparer Présentation'].json;
const slidesRes = $input.first().json;
const presentationId = slidesRes.id || slidesRes.presentationId;
const defaultSlideId = (slidesRes.slides && slidesRes.slides[0] && slidesRes.slides[0].objectId) ? slidesRes.slides[0].objectId : null;

let requests = prep.batch_requests ? [...prep.batch_requests] : [];

// Si une diapositive vierge initiale par défaut a été créée par Google Slides, on la supprime à la fin
if (defaultSlideId && requests.length > 0) {
  requests.push({
    deleteObject: {
      objectId: defaultSlideId
    }
  });
}

return [{
  json: {
    presentation_id: presentationId,
    presentation_url: 'https://docs.google.com/presentation/d/' + presentationId,
    titre: prep.titre,
    theme: prep.theme,
    slides_count: prep.slides_count,
    filename: prep.filename,
    download_url: prep.download_url,
    requests: requests
  }
}];

const prepData = $node['Préparer Requêtes Batch Slides'].json;
const httpResult = $input.first().json;

const hasError = httpResult && (httpResult.error !== undefined || (httpResult.statusCode && httpResult.statusCode >= 400));

return [{
  json: {
    status: 'success',
    reply: 'La présentation Google Slides ' + prepData.titre + ' a été créée et mise en page avec succès (' + prepData.slides_count + ' diapositives).',
    titre: prepData.titre,
    theme: prepData.theme,
    slides_count: prepData.slides_count,
    presentation_id: prepData.presentation_id,
    presentation_url: prepData.presentation_url,
    download_url: prepData.download_url,
    filename: prepData.filename,
    batch_applied: !hasError,
    timestamp: new Date().toISOString()
  }
}];

const body = $input.first().json.body || $input.first().json || {};
const typeEntree = (body.type_entree || 'note').trim().toLowerCase();
const titre = (body.titre || 'Note rapide').trim();
const contenu = (body.contenu || '').trim();
const tags = Array.isArray(body.tags) ? body.tags : [];

return [{
  json: {
    type_entree: typeEntree,
    titre: titre,
    contenu: contenu,
    tags: tags,
    database_id: body.database_id || 'jarvis_default_notes_db',
    created_at: new Date().toISOString()
  }
}];

const prep = $node['Formater Entrée Notion'].json;
const notionRes = $input.first().json;

return [{
  json: {
    status: 'success',
    reply: 'L entrée ' + prep.titre + ' (' + prep.type_entree + ') a été enregistrée dans Notion.',
    titre: prep.titre,
    type_entree: prep.type_entree,
    notion_id: notionRes.id || ('notion_item_' + Date.now()),
    notion_url: notionRes.url || 'https://notion.so/jarvis-notes',
    tags: prep.tags,
    timestamp: new Date().toISOString()
  }
}];
